ALTER TABLE employment_and_income ADD COLUMN fsi numeric;

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT e.emplcoreref, e.debincratio, ea.liqassets, ea.bankaccbal, ea.savamount, e.mthincome FROM employment_and_income e JOIN expenses_and_assets ea ON e.emplcoreref = ea.expemplref LOOP
        UPDATE employment_and_income SET fsi = ROUND(CAST((0.3 * LEAST(1.0, (1 - r.debincratio)) + 0.3 * LEAST(1.0, r.liqassets / (r.mthincome * 6)) + 0.2 * LEAST(1.0, r.bankaccbal / (r.mthincome * 3)) + 0.2 * LEAST(1.0, r.savamount / (r.mthincome * 12))) AS numeric), 4) WHERE emplcoreref = r.emplcoreref;
    END LOOP;
END $$;

